#include <iostream>
#include <iomanip>
#include <string>
#include <stdexcept>

class CommissionEmployee {
public:
    CommissionEmployee(const std::string& first, const std::string& last,
                       const std::string& ssn, double sales = 0.0, double rate = 0.0)
        : firstName{first}, lastName{last}, socialSecurityNumber{ssn} {
        setGrossSales(sales);
        setCommissionRate(rate);
    }

    void setFirstName(const std::string& first) { firstName = first; }
    std::string getFirstName() const { return firstName; }

    void setLastName(const std::string& last) { lastName = last; }
    std::string getLastName() const { return lastName; }

    void setSocialSecurityNumber(const std::string& ssn) { socialSecurityNumber = ssn; }
    std::string getSocialSecurityNumber() const { return socialSecurityNumber; }

    void setGrossSales(double sales) {
        if (sales >= 0.0) {
            grossSales = sales;
        } else {
            throw std::invalid_argument("Gross sales must be >= 0.0");
        }
    }
    double getGrossSales() const { return grossSales; }

    void setCommissionRate(double rate) {
        if (rate > 0.0 && rate < 1.0) {
            commissionRate = rate;
        } else {
            throw std::invalid_argument("Commission rate must be > 0.0 and < 1.0");
        }
    }
    double getCommissionRate() const { return commissionRate; }

    double earnings() const {
        return commissionRate * grossSales;
    }

    void print() const {
        std::cout << "commission employee: " << firstName << ' ' << lastName
                  << "\nsocial security number: " << socialSecurityNumber
                  << "\ngross sales: " << grossSales
                  << "\ncommission rate: " << commissionRate;
    }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
    double grossSales{0.0};
    double commissionRate{0.0};
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    CommissionEmployee emp{"Sue", "Jones", "222-22-2222", 10000.0, 0.06};

    std::cout << "Employee information obtained by get functions:\n"
              << "\nFirst name is " << emp.getFirstName()
              << "\nLast name is " << emp.getLastName()
              << "\nSocial security number is " << emp.getSocialSecurityNumber()
              << "\nGross sales is " << emp.getGrossSales()
              << "\nCommission rate is " << emp.getCommissionRate() << "\n\n";

    emp.setGrossSales(8000.0);
    emp.setCommissionRate(0.1);

    std::cout << "Updated employee information output by print function:\n\n";
    emp.print();
    std::cout << "\n\nEmployee's earnings: $" << emp.earnings() << "\n";

    try {
        emp.setCommissionRate(1.5); // Invalid rate
    } catch (const std::invalid_argument& ex) {
        std::cout << "Validation caught expected error: " << ex.what() << "\n";
    }

    return 0;
}
